import React, { useState, useEffect } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { getOrderById, cancelOrder, reorder } from '../services/api';
import { isAuthenticated } from '../util/auth';

const OrderDetails = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [order, setOrder] = useState(null);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState(false);

  useEffect(() => {
    if (!isAuthenticated()) {
      navigate('/login');
      return;
    }
    fetchOrder();
  }, [id]);

  const fetchOrder = async () => {
    try {
      setLoading(true);
      const res = await getOrderById(id);
      setOrder(res.data);
    } catch (error) {
      console.error('Error fetching order:', error);
      navigate('/account');
    } finally {
      setLoading(false);
    }
  };

  const getStatusClass = (status) => {
    const classes = {
      processing: 'bg-blue-100 text-blue-800 border-blue-300',
      confirmed: 'bg-indigo-100 text-indigo-800 border-indigo-300',
      shipped: 'bg-purple-100 text-purple-800 border-purple-300',
      delivered: 'bg-green-100 text-green-800 border-green-300',
      cancelled: 'bg-red-100 text-red-800 border-red-300'
    };
    return classes[status] || 'bg-gray-100 text-gray-800 border-gray-300';
  };

const getStepNumber = (status) => {
    const steps = {
      processing: 1,
      confirmed: 2,
      shipped: 3,
      delivered: 4,
      cancelled: 0
    };
    return steps[status] || 0;
  };

  const handleCancelOrder = async () => {
    if (!window.confirm('Are you sure you want to cancel this order?')) return;
    
    try {
      setActionLoading(true);
      await cancelOrder(id);
      fetchOrder();
    } catch (error) {
      alert(error.response?.data?.message || 'Error cancelling order');
    } finally {
      setActionLoading(false);
    }
  };

  const handleReorder = async () => {
    try {
      setActionLoading(true);
      await reorder(id);
      navigate('/cart');
    } catch (error) {
      alert(error.response?.data?.message || 'Error reordering');
    } finally {
      setActionLoading(false);
    }
  };

  const canCancel = ['processing', 'confirmed'].includes(order?.orderStatus);

  if (loading) {
    return (
      <div className="flex justify-center py-12">
        <div className="spinner"></div>
      </div>
    );
  }

  if (!order) {
    return (
      <div className="fade-in">
        <div className="empty-state">
          <h3 className="text-xl font-semibold text-gray-800 mb-2">Order not found</h3>
          <Link to="/account" className="btn btn-primary">Back to Account</Link>
        </div>
      </div>
    );
  }

  const currentStep = getStepNumber(order.orderStatus);

  return (
    <div className="fade-in">
      <div className="mb-6">
        <Link to="/account" className="text-primary-600 hover:text-primary-700 flex items-center gap-2">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
          </svg>
          Back to My Orders
        </Link>
      </div>

      {/* Order Header */}
      <div className="card p-6 mb-6">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold text-gray-800">Order #{order._id.slice(-8).toUpperCase()}</h1>
            <p className="text-gray-600 mt-1">
              Placed on {new Date(order.createdAt).toLocaleDateString('en-IN', {
                year: 'numeric',
                month: 'long',
                day: 'numeric'
              })}
            </p>
          </div>
<div className="flex items-center gap-4">
            <span className={`px-4 py-2 rounded-full font-medium border ${getStatusClass(order.orderStatus)}`}>
              {order.orderStatus.charAt(0).toUpperCase() + order.orderStatus.slice(1)}
            </span>
          </div>
        </div>
        
        {/* Action Buttons */}
        <div className="flex flex-wrap gap-3 mt-4">
          {canCancel && (
            <button
              onClick={handleCancelOrder}
              disabled={actionLoading}
              className="btn bg-red-600 text-white hover:bg-red-700 disabled:opacity-50"
            >
              {actionLoading ? 'Cancelling...' : 'Cancel Order'}
            </button>
          )}
          {order.orderStatus === 'delivered' && (
            <button
              onClick={handleReorder}
              disabled={actionLoading}
              className="btn btn-primary disabled:opacity-50"
            >
              {actionLoading ? 'Adding...' : 'Reorder'}
            </button>
          )}
        </div>
      </div>

      {/* Order Tracking Progress */}
      {order.orderStatus !== 'cancelled' && (
        <div className="card p-6 mb-6">
          <h2 className="text-lg font-semibold text-gray-800 mb-6">Order Tracking</h2>
          
          {/* Progress Steps */}
          <div className="relative">
            <div className="flex items-center justify-between">
              {['Processing', 'Confirmed', 'Shipped', 'Delivered'].map((step, index) => (
                <div key={step} className="flex flex-col items-center flex-1 relative z-10">
                  <div className={`w-10 h-10 rounded-full flex items-center justify-center font-semibold ${
                    currentStep > index
                      ? 'bg-green-500 text-white'
                      : currentStep === index + 1
                        ? 'bg-primary-600 text-white'
                        : 'bg-gray-200 text-gray-500'
                  }`}>
                    {currentStep > index + 1 ? (
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                      </svg>
                    ) : (
                      index + 1
                    )}
                  </div>
                  <span className={`mt-2 text-sm font-medium ${
                    currentStep > index
                      ? 'text-green-600'
                      : currentStep === index + 1
                        ? 'text-primary-600'
                        : 'text-gray-500'
                  }`}>
                    {step}
                  </span>
                </div>
              ))}
            </div>
            
            {/* Progress Line */}
            <div className="absolute top-5 left-0 right-0 h-1 bg-gray-200 -z-0 transform -translate-y-1/2">
              <div 
                className="h-full bg-green-500 transition-all duration-500"
                style={{ width: `${((currentStep - 1) / 3) * 100}%` }}
              ></div>
            </div>
          </div>

          {/* Tracking Info */}
          {order.tracking && order.tracking.trackingNumber && (
            <div className="mt-6 pt-6 border-t">
              <div className="grid md:grid-cols-2 gap-4">
                <div>
                  <p className="text-sm text-gray-600">Tracking Number</p>
                  <p className="font-semibold text-gray-800">{order.tracking.trackingNumber}</p>
                </div>
                {order.tracking.estimatedDelivery && (
                  <div>
                    <p className="text-sm text-gray-600">Estimated Delivery</p>
                    <p className="font-semibold text-gray-800">
                      {new Date(order.tracking.estimatedDelivery).toLocaleDateString('en-IN')}
                    </p>
                  </div>
                )}
                {order.tracking.currentLocation && (
                  <div className="md:col-span-2">
                    <p className="text-sm text-gray-600">Current Location</p>
                    <p className="font-semibold text-gray-800">{order.tracking.currentLocation}</p>
                  </div>
                )}
              </div>

              {/* Tracking Timeline */}
              {order.tracking.updates && order.tracking.updates.length > 0 && (
                <div className="mt-6">
                  <h3 className="font-semibold text-gray-800 mb-4">Tracking Timeline</h3>
                  <div className="space-y-4">
                    {order.tracking.updates.map((update, index) => (
                      <div key={index} className="flex gap-4">
                        <div className="flex flex-col items-center">
                          <div className="w-3 h-3 bg-primary-600 rounded-full"></div>
                          {index < order.tracking.updates.length - 1 && (
                            <div className="w-0.5 h-full bg-gray-200 mt-1"></div>
                          )}
                        </div>
                        <div className="flex-1 pb-4">
                          <p className="font-medium text-gray-800">{update.status}</p>
                          <p className="text-sm text-gray-600">{update.description}</p>
                          <p className="text-xs text-gray-500 mt-1">
                            {new Date(update.timestamp).toLocaleString('en-IN')}
                          </p>
                          {update.location && (
                            <p className="text-sm text-gray-500 mt-1">📍 {update.location}</p>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      )}

      {/* Order Items */}
      <div className="card p-6 mb-6">
        <h2 className="text-lg font-semibold text-gray-800 mb-4">Order Items</h2>
        <div className="space-y-4">
          {order.orderItems.map((item, index) => (
            <div key={index} className="flex items-center gap-4 p-4 border border-gray-200 rounded-lg">
              {item.image ? (
                <img 
                  src={item.image} 
                  alt={item.name}
                  className="w-16 h-16 object-cover rounded-lg"
                />
              ) : (
                <div className="w-16 h-16 bg-gray-100 rounded-lg flex items-center justify-center">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" />
                  </svg>
                </div>
              )}
              <div className="flex-1">
                <h3 className="font-semibold text-gray-800">{item.name}</h3>
                <p className="text-sm text-gray-600">Qty: {item.quantity} {item.unit}</p>
                <p className="text-sm text-gray-600">₹{item.price}/{item.unit}</p>
              </div>
              <div className="text-right">
                <p className="font-semibold text-gray-800">₹{item.price * item.quantity}</p>
              </div>
            </div>
          ))}
        </div>

        <div className="mt-6 pt-6 border-t">
          <div className="space-y-2">
            <div className="flex justify-between">
              <span className="text-gray-600">Subtotal</span>
              <span className="text-gray-800">₹{order.totalPrice - 40}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-gray-600">Delivery</span>
              <span className="text-green-600">Free</span>
            </div>
            <div className="flex justify-between text-lg font-semibold">
              <span>Total</span>
              <span className="text-primary-600">₹{order.totalPrice}</span>
            </div>
          </div>
        </div>
      </div>

      {/* Shipping Address */}
      <div className="card p-6">
        <h2 className="text-lg font-semibold text-gray-800 mb-4">Shipping Address</h2>
        <div className="text-gray-600">
          <p>{order.shippingAddress?.street}</p>
          <p>{order.shippingAddress?.city}, {order.shippingAddress?.state} - {order.shippingAddress?.pincode}</p>
          <p className="mt-2">📞 {order.shippingAddress?.phone}</p>
        </div>
      </div>
    </div>
  );
};

export default OrderDetails;
